import{_ as i,o as t,c as g,a2 as d}from"./chunks/framework.BauHmMU1.js";const e="data:image/svg+xml;base64,",j=JSON.parse('{"title":"第 3 章 WebSocket 与 HTTP 的区别与联系","description":"","frontmatter":{},"headers":[],"relativePath":"03-http-vs-websocket.md","filePath":"03-http-vs-websocket.md","lastUpdated":1792595797000}'),l={name:"03-http-vs-websocket.md"};function Z(o,I,M,a,c,P){return t(),g("div",null,[...I[0]||(I[0]=[d('<h1 id="第-3-章-websocket-与-http-的区别与联系" tabindex="-1">第 3 章 WebSocket 与 HTTP 的区别与联系 <a class="header-anchor" href="#第-3-章-websocket-与-http-的区别与联系" aria-label="Permalink to &quot;第 3 章 WebSocket 与 HTTP 的区别与联系&quot;">​</a></h1><h2 id="_3-1-联系-websocket-站在-http-的肩膀上" tabindex="-1">3.1 联系：WebSocket 站在 HTTP 的肩膀上 <a class="header-anchor" href="#_3-1-联系-websocket-站在-http-的肩膀上" aria-label="Permalink to &quot;3.1 联系：WebSocket 站在 HTTP 的肩膀上&quot;">​</a></h2><ol><li><strong>握手复用 HTTP</strong>：如第 2 章所示，WebSocket 连接通过标准 HTTP 请求的 <code>Upgrade</code> 机制建立。</li><li><strong>共用端口</strong>：<code>ws://</code> 默认 80 端口，<code>wss://</code> 默认 443 端口，与 HTTP/HTTPS 完全一致——这意味着它能顺利穿过绝大多数防火墙和代理，不需要开放额外端口。</li><li><strong>复用基础设施</strong>：Cookies、TLS 证书、Nginx 反向代理、负载均衡等 HTTP 生态设施都能直接用于 WebSocket。</li></ol><h2 id="_3-2-区别-两种完全不同的通信模型" tabindex="-1">3.2 区别：两种完全不同的通信模型 <a class="header-anchor" href="#_3-2-区别-两种完全不同的通信模型" aria-label="Permalink to &quot;3.2 区别：两种完全不同的通信模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>HTTP</th><th>WebSocket</th></tr></thead><tbody><tr><td><strong>通信模式</strong></td><td>半双工，请求-响应一一对应</td><td>全双工，双方随时主动发送</td></tr><tr><td><strong>连接性质</strong></td><td>短连接（或 keep-alive 复用，但仍是逐请求）</td><td>持久长连接，一次握手长期使用</td></tr><tr><td><strong>消息边界</strong></td><td>一个请求对应一个响应</td><td>流式消息，数量/方向无约束</td></tr><tr><td><strong>头部开销</strong></td><td>每次请求都带完整头部（几百字节）</td><td>握手后帧头最小仅 2 字节</td></tr><tr><td><strong>服务端推送</strong></td><td>不支持（只能靠轮询/SSE 变通）</td><td>原生支持</td></tr><tr><td><strong>状态保持</strong></td><td>无状态（靠 Cookie/Session 模拟）</td><td>有状态（连接本身即会话）</td></tr><tr><td><strong>URI scheme</strong></td><td><code>http://</code> / <code>https://</code></td><td><code>ws://</code> / <code>wss://</code></td></tr><tr><td><strong>协议层</strong></td><td>应用层协议</td><td>基于 TCP 的应用层协议（握手借道 HTTP）</td></tr></tbody></table><p><img src="'+e+'" alt="HTTP 与 WebSocket 通信模型对比"></p><h2 id="_3-3-如何选择" tabindex="-1">3.3 如何选择？ <a class="header-anchor" href="#_3-3-如何选择" aria-label="Permalink to &quot;3.3 如何选择？&quot;">​</a></h2><ul><li>数据偶尔获取、CRUD 操作、RESTful 资源访问 → <strong>HTTP</strong></li><li>服务端单向推送、低频通知 → <strong>SSE</strong>（比 WebSocket 更简单，自动重连内建）</li><li>双向高频交互、实时性要求高 → <strong>WebSocket</strong></li></ul><p>实际项目中两者常共存：HTTP API 负责登录、数据查询，WebSocket 负责实时推送。</p><hr>',10)])])}const b=i(l,[["render",Z]]);export{j as __pageData,b as default};
